from fastapi import APIRouter, Depends, HTTPException
from ray.util.state import list_actors

router = APIRouter(prefix="/telemetry/ray")

@router.get("/deployments/{deployment_name}/metrics")
async def get_deployment_runtime_telemetry(
    deployment_name: str,
    policy_svc: DeploymentPolicyService = Depends(get_policy_service),
    current_user: User = Depends(get_current_user)
):
    if not policy_svc.can_view_metrics(current_user.tenant_id, deployment_name):
        raise HTTPException(status_code=403, detail="Forbidden: Cannot view metrics for this deployment")

    actors = list_actors(filters=[("class_name", "=", f"ServeActor:{deployment_name}")])
    if not actors:
        raise HTTPException(status_code=404, detail="No active worker actors found for deployment")

    telemetry = [
        {"actor_id": a.actor_id, "pid": a.pid, "node_ip": a.node_ip_address, "state": a.state}
        for a in actors
    ]
    return {"deployment": deployment_name, "active_actors": len(telemetry), "actors": telemetry}
